    function testRegression_property() public {
        address baseToken = address(0x1234);
        address nft = address(0x5678);
        c.initialize(baseToken, nft, 1000, 1000, 100, 100, bytes32(0), false, false);
        bool ok;
        try c.availableForFlashLoan(nft, 0) { ok = true; } catch { ok = false; }
